	// nil 表示未注入（只会发生在测试或 bootstrap 顺序出错时）
	restart     func(reason string) bool
	pty         *ptyhost.Host
	ptyRootPath string
	// B156.3 自动化层：编制域与 keystone 域的服务引用，cmd 组装点装配注入。
	// B233.14：编制域字段是使用方接口 SchedulingClient；具体 *scheduling.Service
	// 只在 cmd 组装点构造后经 SetScheduling 注入，本文件不再 new。
	// B233.18：keystone/hostapi 同款——构造上移 cmd 组装点，经 SetKeystone /
	// SetHostAPI 注入，本文件不再 new。
	scheduling SchedulingClient
	keystone   *keystone.Service
	autoLedger *ledgerapi.Facade
	ptyGate    *ptyapi.Host
	hostAPI    *hostapi.Host
	// B432 iOS 推送扇出：「需要你」事件 → APNs。NewServer 构造（凭据未配齐时
	// sender 为 nil，投递静默降级站内），装配点经 StartPush 起 worker；
	// 两条事件旁路（合成钩子 + 自动化循环）与 badge 同源计数都接在它上面。
	pushFanout *PushFanout
	// B156.2 协作房间：入站门面实例与换绑端口，cmd 组装点装配注入
	// （B233.18：collab.New 构造上移 cmd，经 SetRooms 注入）。
	rooms *collab.Service
	// coordLocks 串行化同一卡的 Launch→席位 CAS；每张卡独立，避免不同卡互相阻塞。
	coordLocksMu sync.Mutex
	coordLocks   map[string]*sync.Mutex
	// 协调者是 print 一次性回合，没有控制台 TUI tab：名额在回合结束即归还
	// （见 scheddrain.go 的 launchCoordinatorRoundWithExpect）。
	// automationStartOnce/automationKick protect the single host automation loop.
	automationStartOnce   sync.Once
	automationKick        chan struct{}
	automationMu          sync.Mutex
	automationCursor      int64
	automationCursorStore *automationCursorStore
	automationSeen        map[int64]struct{}
	// automationBackoff 记录每张卡最近一次失败唤醒的 seq 与退避截止时刻（B389
	// §3.5.4）：同卡同 seq 在退避窗内不重复试跑，防止失败事件反复引发唤醒。
	// 进程内存：重启后重试一次是安全方向（不丢事件）。
	automationBackoff map[string]wakeBackoff
	// automationStall 是每张卡连续「协调者准入满员」的次数（B390 P4）。它**不是**
	// 重试载体——重试靠 B389 的认领挡水位、下一轮自然重读（不 completeWakeBatch、
	// 不标 seen）；这里只数连续失败次数，用于恰一次落 needs_human 的去重阈值。
	// 成功或遇非准入错误即清。进程内存：重启后重新计数，安全方向。
	automationStall map[string]int
	// desktopWakeStall 是每张卡当前的桌面端失败段（B434 契约 §3.7）：连续失败次数（0→1
	// 落一条 needs_human）、未落盘重试的退避截止与段内复用的 wake_round 轮次。与
	// automationStall 独立（不经 recordAdmissionStall）。受 automationMu 保护；成功即删。
	// 进程内存：重启清零，同段最多多落一条 needs_human（契约写明可接受）。
	desktopWakeStall map[string]desktopWakeStallEntry
	// wakeQueueRounds 锁定「一轮」的队列路径身份：IgnitionRequest 身份键
	// （wakeQueueRoundKey）→ 未收尾的 wake roundID。契约是「同一 IgnitionRequest
	// 为一轮」（plan r2），不是「同一卡为一轮」——同卡换节点是新请求、新开一轮
	// （B393 review-4 major）。drainIgnitionRequest 出队失败回填后，2s 重试是
	// 同一请求必须复用同一 roundID——否则 EnsureComment 键随 nextWakeRoundID
	// 每次漂移，D4/转交失败/本机 Wake 失败三条出口会无界刷 fail 行（B393 复评
	// major）。成功收尾时按请求键摘除。进程内存：重启后重开一轮是安全方向
	// （最多多落一组，不会吞行）。
	wakeQueueRoundsMu sync.Mutex
	wakeQueueRounds   map[string]string
	// automationRoundHook is a test-only observation point; production leaves it nil.
	automationRoundHook func(card string, result keystone.RoundResult)
	// desktopMu 保护薄壳状态：上报与控制台读取来自不同 HTTP 连接。
	desktopMu    sync.Mutex
	desktopState *proto.DesktopState
	desktopAt    time.Time
	// desktopNow 是 TTL 测试缝；生产为 nil，使用 time.Now。
	desktopNow func() time.Time
	// desktopOpen 把 claude://code/continue 深链交给本机 Claude 桌面端（B434 契约 §3.7）。
	// NewServer 不装配（测试进程永远拿不到真实 opener）；生产由 cmd/agentd.go 组装点经
	// SetDesktopOpener(PlatformDesktopOpener(runtime.GOOS)) 装配（darwin `open`、其它平台报
	// 「本平台不支持 Claude 桌面端深链」，契约 r12 第 3 条）；同包测试直接赋 spy。
	// nil = 本机不能发深链：wakeDesktopSeat 按「信已落盘、continue 未发出」返回
	// desktopUnopenedError。只在装配期写、运行期只读，不加锁。
	desktopOpen desktopOpener
	// desktopHome 是桌面端信箱的根目录（信箱 = <desktopHome>/.handoff/desktop-wake，
	// 契约 r10 第 11 条）。空 = os.UserHomeDir()（信箱属写信进程用户）；测试注入
	// t.TempDir()，不改进程 HOME。只在装配期写、运行期只读，不加锁。
	desktopHome string
	// upgradeMu / machineUpgrades 保护后台执行机升级：同一台机器同时只允许一个，
	// 且记住最近一次的终态——**终态是控制台唯一的「失败出口」**（见
	// proto.MachineUpgrade 的说明），丢了它界面就会一直停在「升级中」。
	// 进程内存，agentd 重启即清空：这是诚实的，重启后本进程确实不知道。
	upgradeMu       sync.Mutex
	machineUpgrades map[string]*proto.MachineUpgrade
	// machineUpgradeInstaller 是远端升级共用的资产下载器；测试用 runner 缝整体替换。
	machineUpgradeInstaller *release.Installer
	machineUpgradeRunner    machineUpgradeRunner
	// pool 是对 target 的客户端复用池（探活/镜像/项目树/PTY/升级共用）。
	//
	// 为什么在 NewServer 里自建而不是靠注入：NewServer 有约 50 个调用点，
	// 靠注入必然漏，而漏掉的表现是运行时空指针。池的构造零成本（不发请求），
	// 自建没有代价。
	pool          *targetclient.Pool
	previewOwner  *workspace.PreviewOwner
	previewOpener PreviewOpener
	previewMirror *PreviewMirror
	// cardStepMu / cardStepFlight 守「同一张卡同时只允许一个环节在飞」。
	// 进程内状态：重启即清空，见 cardstep.go 的边界说明。
	cardStepMu     sync.Mutex
	cardStepFlight map[string]bool
	// runStepFn 是环节执行的落点，只为测试可替换而存在：生产恒为 s.runStep。
	// 环节要跑几十分钟且会真派 task，单测替换掉它才能验「在飞集合」这类装配逻辑。
	runStepFn func(ctx context.Context, runner *ledgerstep.StepRunner, cardID, step string)
}

